\label{lem:restricted-product}
Let $a,y,s$ be positive integers and suppose
$y<2^a-1$ and $s<a(2^a-1)$. Then $s=ay$ if and only if there exist
positive integers $u,q$ such that
\begin{align}
 2^a u+1&=u+2^s,\label{eq:mersenne-first}\\
 2^a q+y+1&=u+q+2^a.\label{eq:mersenne-second}
\end{align}

\label{thm:width}
For $m\geq1$, the class of finite order forests of width at most $m$
has JEP if and only if $m\leq3$.

[Saturation at a limit]\label{lem:saturation}
For every nonzero limit $\lambda$ and $b\in\N$,
$\norm(M(\lambda,b))=b$.  The maximum strictly increases with $b$.

[Effective complete lattices]\label{lem:lattices}
The domains in \ref{def:domains} are finite complete lattices, effectively
enumerable from the inputs.  Weakening preserves their joins and meets.

[A finite monotone operator]\label{lem:operator}
$F$ preserves natural coherent families and is monotone.  Iteration from
bottom reaches its least fixed point in finitely many steps.

[Adequacy]\label{lem:adequacy}
At the fixed point, a weak or strict observation bit is true exactly when the
corresponding finite recursive comparison is derivable.

[Template grafting]\label{lem:graft}
For an ordinary template $A$ and $p\succeq_*q$ of the same type,
$A[x:=p]\succeq_*A[x:=q]$, even if $p$ contains marked subterms.

[Explicit application contexts]\label{lem:context}
If ordinary $a\succ_*b$, replacing $a$ by $b$ in any ordinary context gives
another strict comparison.

[Arithmetic accessibility proof]\label{lem:id1}
For this fixed $S$, $\mathrm{ID}_1$ proves that every well-typed auxiliary
term is accessible under $R$.

[Iteration inequalities]\label{lem:iterationedges}
$W_i\succ_cU$.  If $i\succ_cj$ then
$W_i\succ_cW_j$ and $W_i\succ_cPW_j$.

[Zero, successor and a finite cap]\label{lem:primitives}
Closed native terms realize $0$, right successor and $\omega$.
For every $P:B\to B,U:B$, a closed term lies strictly above every $P^nU$.

[Exact successor cut and count cocycle]\label{lem:successor}
Let $\theta=\omega^\gamma\ge\omega$, $L=\theta\omega$, and
$w=\norm\theta$. On the common genuine domain $t\ge c+w+\norm L$,
\begin{align}
 \KK Lc(t)&=\KK\theta c(\KK L{c+w}(t)),              \label{eq:cut}\\
 \EE Lc(t)&=\EE L{c+w}(t)
        +\EE\theta c(\KK L{c+w}(t)).                \label{eq:cocycle}
\end{align}

[Ground-open source equality]\label{cor:sourceeq}
Universal equality of literal canonical assignment vectors is decidable
for any original source pair whose free names all have ground type.

[Snyatkov's arithmetic supplier]\label{thm:snyatkov}
The first-order theory $\operatorname{Th}(\N;0,1,+,<,f)$, with the exact
function in \eqref{eq:f}, is decidable.

[Exact block recursion]\label{lem:kernel-recursion}
One has
\[
 E^1_c=1,\quad X^1_c=f,\qquad
 E^2_c(t)=f(t)/2-\lceil c/2\rceil+1.
\]
Define
\begin{equation}\label{eq:V}
 V_j(t)=f^{\,f(t)/2+j+1}(t).
\end{equation}
Then $X^2_{c,j}=V_{j-\lceil c/2\rceil}$. For $d\ge2$, on a computable tail,
\begin{align}
 X^d_{c,j}&=X^{d-1}_{c,j}\circ X^d_{c+d},\label{eq:Xrec}\\
 E^d_c&=E^{d-1}_c\circ X^d_{c+d}+E^d_{c+d}.\label{eq:Erec}
\end{align}

[Counter expansion and collision]\label{lem:counter}
On an effective tail,
\begin{equation}\label{eq:counter-expand}
 E^r_c(t)=\frac H2+1-\lceil c/2\rceil
                  +\sum_{h=3}^r E^h_{c+h}(A_h),
 \qquad \frac H2<E^r_c(t)<\frac{3H}{4}.
\end{equation}
Suppose counters of ranks $r\ge s\ge3$ have equal leaders. Then they
have the same prefix index $c$. If $r=s$ their whole values are equal;
if $r>s$ the smaller-rank input is the corresponding $A_s$, and
\begin{equation}\label{eq:collision}
 E^r_c(t)-E^s_c(A_s)=\sum_{h=s+1}^r E^h_{c+h}(A_h).
\end{equation}
Every counter introduced on the right has rank strictly greater than $s$.
For distinct leaders, counter order agrees with leader order. Equal
leaders are ordered by counter rank, with equality at equal rank.

[Effective residues of kernels and counters]\label{lem:kernel-residues}
For each fixed $d,c,j,m$, both $X^d_{c,j}$ and $E^d_c$ have an effectively
computable constant residue modulo $m$ on a computable tail. The $X$
residue is $r_m$. A valid counter residue is
\begin{equation}\label{eq:E-residue}
 E^d_c(t)\equiv
 p_d\bigl((r_{Q_d}-c)\bmod Q_d\bigr)\pmod m,
 \qquad Q_d=d!m^{d-1},
\end{equation}
where $p_d(n)$ counts partitions of $n$ into parts at most $d$.

[Sparse endpoint comparison]\label{lem:endpoints}
For a fixed nonzero limit $\lambda$, $J_\lambda$ is strictly increasing.
Its distinct norm inputs have distinct terminal endpoints, ordered in the
same way. For any two distinct endpoints $Z<W$ one has
\begin{equation}\label{eq:sparse}
 W\ge2^{Z+1}.
\end{equation}
Every value with endpoint $Z$ lies strictly between $Z$ and $2Z$ and below
the next value of $f$.

[Ground weak/strict equivalence]\label{cor:ground-equivalence}
On all actual ground-output sources with ground free variables, universal
weak and strict comparison are polynomial-DAG many-one interreducible.

[Uniform residue envelopes]\label{thm:envelope}
There is an effective function $m\mapsto r_m\in\{0,\ldots,m-1\}$ such
that:
\begin{enumerate}
\item $f(x)\equiv r_m\pmod m$ for $x\ge m$;
\item for $s\ge1$, $j\ge2$ and $m\le2^{2^s}$,
      $F_j(s)\equiv r_m\pmod m$;
\item if $B=f(u)$, then
      $f(u+1)\equiv r_m\pmod m$ for every $m\le2^{2^B}$.
\end{enumerate}

\label{lem:push}
If $h:\R\to\Q$ is additive, $h_*p$ is an additive idempotent
ultrafilter on $\Q$. If it is principal, it is principal at zero.

\label{lem:length}
For every $k\in\N$, the set $S_k=\{x:\ell(x)=k\}$ is not in $p$.
Consequently $\{x:\ell(x)>m\}\in p$ for every $m\in\N$.

\label{lem:three}
For fixed literal sentences $\sigma,\tau$:
\begin{enumerate}
\item if $D\vdash\sigma$, then $D\vdash E_A(\sigma)$;
\item $D\vdash E_A(\sigma\to\tau)\to(E_A(\sigma)\to E_A(\tau))$;
\item $D\vdash\Prv_D(\code\sigma)\to E_A(\sigma)$.
\end{enumerate}

\label{prop:positive}
If source agents are deterministic or target agents are stochastic,
there is a transformation.

\label{prop:negative}
There is no transformation with stochastic source agents and
deterministic target agents, for either environment type.

\label{prop:noncomposition}
There are transformations $F\to G$ and $G\to H$ whose naturally
composed maps fail both nontriviality conditions.

\label{thm:original}
There is a fixed coding-dependent $m_0$ such that:
\begin{enumerate}
\item for every fixed $m\ge m_0$, the predicate
      $H_{\mathrm{PR}}(p)\ge m$ is $\Pi^0_3$-complete on total
      predictor indices;
\item $H_{\mathrm{PR}}(p)=\infty$ is $\Pi^0_3$-complete on the same
      promise;
\item $H_{\mathrm{PR}}$ and the strict comparison relation between
      two such values have exact oracle degree $0'''$.
\end{enumerate}
The reductions witnessing hardness uniformly produce total predictors.

\label{lem:membership}
Uniformly in an ordinary program index for a total computable $f$,
membership $e\in E_f$ has a recursive-matrix $\Sigma^0_2$ definition.

\label{prop:threshold}
Uniformly in total binary $p$ and an ordinary total bound program $f$,
$T(p,f)$ has a recursive-matrix $\Pi^0_3$ definition.

\label{lem:finitevalues}
For any listing of all total computable functions, every total
predictor has a finite $H_g$ value.

\label{lem:constants}
An element algebraic over $\Q$ in a differential extension is a
constant. A nonconstant element is therefore transcendental over $\Q$.

\label{thm:orderone}
On these source-valid inputs:
\begin{enumerate}
\item if $r\ne0$, then $\Con_\Q(p,q)$ holds exactly when
      $\rad(r)\mid q$ in $\Q[Y]$;
\item if $r=0$, then $\Con_\Q(p,q)$ fails for every nonzero $q$.
\end{enumerate}

\label{lem:curve}
Any two nonconstant solutions of $p(a,Da)=0$ generate differential
fields isomorphic over $\Q$ by a map sending one solution to the other.

\label{lem:genericcurve}
If $r\ne0$, there exists a nonconstant solution avoiding every
specified nonzero $q(Y)$.

\label{lem:weights}
If all $x_i$ are nonzero and $Dx_i=\lambda_ix_i$, they are
algebraically independent over $K$.
